      $('detailBody').innerHTML += actions([['scanQuark','\u626B\u7801\u767B\u5F55','secondary'],['registerQuark','\u5938\u514B\u6CE8\u518C','register']]) + qrBoxHtml();
      $('saveQuark').onclick = () => saveCredential('quark','cookie',$('quarkCookie').value);
