      $('detailBody').innerHTML = '<div class="row">' + input('thunderMobile','\u624B\u673A\u53F7','') + input('thunderCode','\u9A8C\u8BC1\u7801','') + '</div>' +
        actions([['sendThunderSms','\u53D1\u9001\u9A8C\u8BC1\u7801','primary'],['loginThunderSms','\u767B\u5F55','secondary'],['registerThunder','\u8FC5\u96F7\u6CE8\u518C','register'],['clearThunder','\u6E05\u9664\u767B\u5F55','danger']]) +
        textarea('thunderCfg','thunderCfg',secrets.thunder.config) + actions([['saveThunderCfg','\u4FDD\u5B58 thunderCfg','primary']]);
      $('sendThunderSms').onclick = sendThunderSms;
